def transform(grid):
    # The isolated 5s mark cells to erase or repair. Keep 5s that occur in
    # the rectangular footprint of a large color object; replace those with
    # the object's color, and erase all other 5s.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    positions = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 5):
                positions.setdefault(grid[r][c], []).append((r, c))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                out[r][c] = 0
                for color, pts in positions.items():
                    ys = [p[0] for p in pts]
                    xs = [p[1] for p in pts]
                    # Repair only if the cell lies inside the bounding box of
                    # a substantial, nearly rectangular colored object.
                    if len(pts) >= 4 and min(ys) <= r <= max(ys) and min(xs) <= c <= max(xs):
